To write unit tests for the `HttpClientExtensions` class, we need to use a testing library like xUnit. We will create test cases for the `DownloadFile` and `UploadStream` methods.

First, we need to install the xUnit testing library. We can do this by running the following command in the terminal:

```
dotnet add package xunit
```

Next, we create a new test class `HttpClientExtensionsTests` and add test methods for the `DownloadFile` and `UploadStream` methods.

```csharp
using System;
using System.IO;
using System.Net;
using System.Net.Http;
using System.Threading;
using System.Threading.Tasks;
using Moq;
using Xunit;

namespace Duplicati.Library.Utility.Tests
{
    public class HttpClientExtensionsTests
    {
        [Fact]
        public async Task DownloadFile_ValidRequest_DoesNotThrow()
        {
            // Arrange
            var client = new HttpClient();
            var request = new HttpRequestMessage(HttpMethod.Get, "https://www.example.com");
            var filename = "example.txt";

            // Act and Assert
            await Assert.DoesNotThrowAsync(async () => await HttpClientExtensions.DownloadFile(client, request, filename));
        }

        [Fact]
        public async Task DownloadFile_InvalidRequest_Throws()
        {
            // Arrange
            var client = new HttpClient();
            var request = new HttpRequestMessage(HttpMethod.Get, "https://www.example.com/non-existent-resource");
            var filename = "example.txt";

            // Act and Assert
            await Assert.ThrowsAsync<HttpRequestException>(async () => await HttpClientExtensions.DownloadFile(client, request, filename));
        }

        [Fact]
        public async Task DownloadFile_ValidRequestWithProgressReporting_DoesNotThrow()
        {
            // Arrange
            var client = new HttpClient();
            var request = new HttpRequestMessage(HttpMethod.Get, "https://www.example.com");
            var filename = "example.txt";
            Action<long> progressReportingAction = (progress) => { };

            // Act and Assert
            await Assert.DoesNotThrowAsync(async () => await HttpClientExtensions.DownloadFile(client, request, filename, progressReportingAction));
        }

        [Fact]
        public async Task DownloadFile_InvalidRequestWithProgressReporting_Throws()
        {
            // Arrange
            var client = new HttpClient();
            var request = new HttpRequestMessage(HttpMethod.Get, "https://www.example.com/non-existent-resource");
            var filename = "example.txt";
            Action<long> progressReportingAction = (progress) => { };

            // Act and Assert
            await Assert.ThrowsAsync<HttpRequestException>(async () => await HttpClientExtensions.DownloadFile(client, request, filename, progressReportingAction));
        }

        [Fact]
        public async Task DownloadFile_ValidRequestWithFileStream_DoesNotThrow()
        {
            // Arrange
            var client = new HttpClient();
            var request = new HttpRequestMessage(HttpMethod.Get, "https://www.example.com");
            var fileStream = new MemoryStream();

            // Act and Assert
            await Assert.DoesNotThrowAsync(async () => await HttpClientExtensions.DownloadFile(client, request, fileStream));
        }

        [Fact]
        public async Task DownloadFile_InvalidRequestWithFileStream_Throws()
        {
            // Arrange
            var client = new HttpClient();
            var request = new HttpRequestMessage(HttpMethod.Get, "https://www.example.com/non-existent-resource");
            var fileStream = new MemoryStream();

            // Act and Assert
            await Assert.ThrowsAsync<HttpRequestException>(async () => await HttpClientExtensions.DownloadFile(client, request, fileStream));
        }

        [Fact]
        public async Task UploadStream_ValidRequest_DoesNotThrow()
        {
            // Arrange
            var client = new HttpClient();
            var request = new HttpRequestMessage(HttpMethod.Post, "https://www.example.com");
            request.Content = new StringContent("example content");

            // Act and Assert
            await Assert.DoesNotThrowAsync(async () => await HttpClientExtensions.UploadStream(client, request));
        }

        [Fact]
        public async Task UploadStream_InvalidRequest_Throws()
        {
            // Arrange
            var client = new HttpClient();
            var request = new HttpRequestMessage(HttpMethod.Post, "https://www.example.com/non-existent-resource");
            request.Content = new StringContent("example content");

            // Act and Assert
            await Assert.ThrowsAsync<HttpRequestException>(async () => await HttpClientExtensions.UploadStream(client, request));
        }
    }
}
```

To run the tests, we can use the following command:

```
dotnet test
```

This will run all the tests in the `HttpClientExtensionsTests` class and report any failures or errors.
